'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Clock, Package, CheckCircle2, AlertCircle, Search, Eye, Printer, RefreshCw } from 'lucide-react';
import '../styles/pos-rush.css';

const mockOpenOrders = [
    {
        id: 'O001',
        orderNumber: '#1001',
        customer: 'John Doe',
        phone: '+1 (555) 123-4567',
        fulfillmentType: 'DINE_IN',
        tableNumber: '12',
        items: 3,
        total: 45.50,
        status: 'PREPARING',
        placedAt: '11:30 AM',
        estimatedReady: '11:45 AM',
        itemsList: ['Large Pizza', 'Garlic Bread', 'Coke'],
        payment: 'CARD'
    },
    {
        id: 'O002',
        orderNumber: '#1002',
        customer: 'Sarah Smith',
        phone: '+1 (555) 234-5678',
        fulfillmentType: 'TAKEAWAY',
        items: 2,
        total: 28.00,
        status: 'READY',
        placedAt: '11:35 AM',
        estimatedReady: '11:50 AM',
        itemsList: ['Medium Pizza', 'Fries'],
        payment: 'CASH'
    },
    {
        id: 'O003',
        orderNumber: '#1003',
        customer: 'Mike Johnson',
        phone: '+1 (555) 345-6789',
        fulfillmentType: 'DELIVERY',
        address: '123 Main St, New York',
        items: 5,
        total: 67.25,
        status: 'PREPARING',
        placedAt: '11:40 AM',
        estimatedReady: '12:00 PM',
        itemsList: ['2x Large Pizza', 'Wings', 'Salad', 'Drinks'],
        payment: 'CARD'
    },
    {
        id: 'O004',
        orderNumber: '#1004',
        customer: 'Emma Davis',
        phone: '+1 (555) 456-7890',
        fulfillmentType: 'DINE_IN',
        tableNumber: '8',
        items: 4,
        total: 52.75,
        status: 'COMPLETED',
        placedAt: '11:20 AM',
        estimatedReady: '11:35 AM',
        completedAt: '11:38 AM',
        itemsList: ['Large Pizza', 'Pasta', 'Salad', 'Wine'],
        payment: 'CARD'
    },
];

export const OpenOrdersPage: React.FC = () => {
    const router = useRouter();
    const [selectedOrder, setSelectedOrder] = useState<typeof mockOpenOrders[0] | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState<'ALL' | 'PREPARING' | 'READY' | 'COMPLETED'>('ALL');

    const filteredOrders = mockOpenOrders.filter(order => {
        const matchesSearch = order.customer.toLowerCase().includes(searchQuery.toLowerCase()) ||
            order.orderNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
            order.phone.includes(searchQuery);
        const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
        return matchesSearch && matchesStatus;
    });

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'PREPARING':
                return { bg: 'rgba(245, 158, 11, 0.1)', border: 'var(--pos-state-warning)', text: 'var(--pos-state-warning)' };
            case 'READY':
                return { bg: 'rgba(16, 185, 129, 0.1)', border: 'var(--pos-state-success)', text: 'var(--pos-state-success)' };
            case 'COMPLETED':
                return { bg: 'rgba(59, 130, 246, 0.1)', border: '#3B82F6', text: '#3B82F6' };
            default:
                return { bg: 'var(--pos-bg-main)', border: 'var(--pos-border-subtle)', text: 'var(--pos-text-secondary)' };
        }
    };

    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'PREPARING': return Clock;
            case 'READY': return Package;
            case 'COMPLETED': return CheckCircle2;
            default: return AlertCircle;
        }
    };

    return (
        <div className="pos-screen" style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            {/* Header */}
            <header style={{
                height: '72px',
                background: 'var(--pos-bg-surface)',
                borderBottom: '1px solid var(--pos-border-subtle)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                padding: '0 24px',
                flexShrink: 0
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                    <div style={{
                        width: '44px',
                        height: '44px',
                        background: 'var(--pos-action-primary)',
                        borderRadius: '12px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                    }}>
                        <Clock size={24} color="white" />
                    </div>
                    <div>
                        <h1 style={{ fontSize: '18px', fontWeight: 800, color: 'var(--pos-text-primary)' }}>
                            OPEN ORDERS
                        </h1>
                        <div style={{ fontSize: '12px', color: 'var(--pos-text-muted)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                            {mockOpenOrders.length} Active System Threads
                        </div>
                    </div>
                </div>

                <div style={{ display: 'flex', gap: '8px' }}>
                    <button className="pos-btn pos-btn-secondary" style={{ height: '48px', padding: '0 16px', fontSize: '13px' }}>
                        <RefreshCw size={18} />
                        REFRESH
                    </button>
                    <button
                        onClick={() => router.push('/pos/dashboard')}
                        className="pos-btn pos-btn-secondary"
                        style={{ height: '48px', padding: '0 16px', fontSize: '13px', background: 'var(--pos-text-primary)', color: 'white' }}
                    >
                        BACK TO DASHBOARD
                    </button>
                </div>
            </header>

            <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>
                {/* LEFT: Orders List */}
                <div style={{
                    width: '450px',
                    background: 'var(--pos-bg-surface)',
                    borderRight: '1px solid var(--pos-border-subtle)',
                    display: 'flex',
                    flexDirection: 'column'
                }}>
                    {/* Search & Filter */}
                    <div style={{ padding: '20px', background: 'var(--pos-bg-main)', borderBottom: '1px solid var(--pos-border-subtle)' }}>
                        <div style={{ position: 'relative', marginBottom: '16px' }}>
                            <Search size={18} style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', color: 'var(--pos-text-muted)' }} />
                            <input
                                type="text"
                                placeholder="Search orders..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="pos-input"
                                style={{ paddingLeft: '48px', height: '52px' }}
                            />
                        </div>

                        {/* Status Filter */}
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '6px' }}>
                            {['ALL', 'PREPARING', 'READY', 'COMPLETED'].map(status => (
                                <button
                                    key={status}
                                    onClick={() => setFilterStatus(status as any)}
                                    style={{
                                        height: '36px',
                                        borderRadius: '8px',
                                        border: '1px solid var(--pos-border-subtle)',
                                        background: filterStatus === status ? 'var(--pos-action-primary)' : 'white',
                                        color: filterStatus === status ? 'white' : 'var(--pos-text-secondary)',
                                        fontSize: '10px',
                                        fontWeight: 800,
                                        textTransform: 'uppercase',
                                        letterSpacing: '0.05em',
                                        cursor: 'pointer',
                                        transition: 'all 0.2s'
                                    }}
                                >
                                    {status}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Orders List */}
                    <div style={{ flex: 1, overflowY: 'auto', padding: '16px' }} className="pos-scroll">
                        {filteredOrders.length > 0 ? (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                {filteredOrders.map(order => {
                                    const statusColor = getStatusColor(order.status);
                                    const StatusIcon = getStatusIcon(order.status);
                                    const isActive = selectedOrder?.id === order.id;

                                    return (
                                        <button
                                            key={order.id}
                                            onClick={() => setSelectedOrder(order)}
                                            style={{
                                                padding: '20px',
                                                background: isActive ? 'var(--pos-bg-main)' : 'white',
                                                border: isActive ? '2px solid var(--pos-action-primary)' : '1px solid var(--pos-border-subtle)',
                                                borderRadius: '16px',
                                                cursor: 'pointer',
                                                textAlign: 'left',
                                                transition: 'all 0.2s',
                                                boxShadow: isActive ? '0 8px 24px rgba(31, 164, 169, 0.12)' : 'none'
                                            }}
                                        >
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
                                                <div>
                                                    <div style={{ fontSize: '20px', fontWeight: 900, color: 'var(--pos-text-primary)', marginBottom: '4px' }}>
                                                        {order.orderNumber}
                                                    </div>
                                                    <div style={{ fontSize: '13px', color: 'var(--pos-text-secondary)', fontWeight: 700 }}>
                                                        {order.customer}
                                                    </div>
                                                    <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 800, textTransform: 'uppercase', marginTop: '4px' }}>
                                                        {order.fulfillmentType.replace('_', ' ')} {order.tableNumber && `• Table ${order.tableNumber}`}
                                                    </div>
                                                </div>
                                                <div style={{
                                                    padding: '6px 10px',
                                                    background: statusColor.bg,
                                                    border: `1px solid ${statusColor.border}`,
                                                    borderRadius: '8px',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: '6px'
                                                }}>
                                                    <StatusIcon size={12} color={statusColor.text} />
                                                    <span style={{ fontSize: '10px', fontWeight: 900, color: statusColor.text, textTransform: 'uppercase' }}>
                                                        {order.status}
                                                    </span>
                                                </div>
                                            </div>

                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                                                <div>
                                                    <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 700, marginBottom: '2px' }}>
                                                        {order.items} items
                                                    </div>
                                                    <div style={{ fontSize: '24px', fontWeight: 900, color: 'var(--pos-text-primary)', letterSpacing: '-0.02em' }}>
                                                        ${order.total.toFixed(2)}
                                                    </div>
                                                </div>
                                                <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 700, textAlign: 'right' }}>
                                                    <div>Placed: {order.placedAt}</div>
                                                    <div>Ready: {order.estimatedReady}</div>
                                                </div>
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        ) : (
                            <div className="pos-empty">
                                <Clock size={48} color="var(--pos-border-subtle)" />
                                <div className="pos-empty-text">No active orders found</div>
                            </div>
                        )}
                    </div>
                </div>

                {/* RIGHT: Order Details */}
                <div style={{ flex: 1, background: 'var(--pos-bg-main)', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
                    {selectedOrder ? (
                        <>
                            <div style={{ flex: 1, overflowY: 'auto', padding: '32px' }} className="pos-scroll">
                                <div style={{ maxWidth: '800px', margin: '0 auto' }}>
                                    {/* Detailed Header */}
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '40px' }}>
                                        <div>
                                            <div style={{ fontSize: '12px', color: 'var(--pos-text-muted)', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '0.2em', marginBottom: '8px' }}>
                                                Order Information
                                            </div>
                                            <h2 style={{ fontSize: '56px', fontWeight: 900, color: 'var(--pos-text-primary)', lineHeight: 1, letterSpacing: '-0.04em' }}>
                                                {selectedOrder.orderNumber}
                                            </h2>
                                        </div>
                                        {(() => {
                                            const statusColor = getStatusColor(selectedOrder.status);
                                            const StatusIcon = getStatusIcon(selectedOrder.status);
                                            return (
                                                <div style={{
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: '12px',
                                                    padding: '16px 24px',
                                                    background: statusColor.bg,
                                                    border: `2px solid ${statusColor.border}`,
                                                    borderRadius: '16px'
                                                }}>
                                                    <StatusIcon size={24} color={statusColor.text} />
                                                    <span style={{ fontSize: '18px', fontWeight: 900, color: statusColor.text, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                                        {selectedOrder.status}
                                                    </span>
                                                </div>
                                            );
                                        })()}
                                    </div>

                                    {/* Action Grid */}
                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '40px' }}>
                                        <div style={{ background: 'white', padding: '24px', borderRadius: '20px', border: '1px solid var(--pos-border-subtle)' }}>
                                            <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 900, textTransform: 'uppercase', marginBottom: '16px' }}>Customer Profile</div>
                                            <div style={{ fontSize: '20px', fontWeight: 800, color: 'var(--pos-text-primary)', marginBottom: '4px' }}>{selectedOrder.customer}</div>
                                            <div style={{ fontSize: '14px', color: 'var(--pos-text-secondary)', fontWeight: 600 }}>{selectedOrder.phone}</div>
                                            <div style={{ marginTop: '16px', display: 'flex', gap: '8px' }}>
                                                <span style={{ padding: '6px 12px', background: 'var(--pos-bg-main)', borderRadius: '8px', fontSize: '11px', fontWeight: 700 }}>VIP MEMBER</span>
                                                <span style={{ padding: '6px 12px', background: 'var(--pos-bg-main)', borderRadius: '8px', fontSize: '11px', fontWeight: 700 }}>{selectedOrder.payment}</span>
                                            </div>
                                        </div>
                                        <div style={{ background: 'white', padding: '24px', borderRadius: '20px', border: '1px solid var(--pos-border-subtle)' }}>
                                            <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 900, textTransform: 'uppercase', marginBottom: '16px' }}>Fulfillment Thread</div>
                                            <div style={{ fontSize: '20px', fontWeight: 800, color: 'var(--pos-text-primary)', marginBottom: '4px' }}>
                                                {selectedOrder.fulfillmentType.replace('_', ' ')}
                                            </div>
                                            <div style={{ fontSize: '14px', color: 'var(--pos-text-secondary)', fontWeight: 600 }}>
                                                {selectedOrder.tableNumber ? `Assigned Table ${selectedOrder.tableNumber}` : selectedOrder.address || 'Standard Pickup'}
                                            </div>
                                            <div style={{ marginTop: '16px', display: 'flex', gap: '8px' }}>
                                                <span style={{ padding: '6px 12px', background: 'var(--pos-bg-main)', borderRadius: '8px', fontSize: '11px', fontWeight: 700 }}>
                                                    PLACED {selectedOrder.placedAt}
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Items List */}
                                    <div style={{ background: 'white', borderRadius: '24px', border: '1px solid var(--pos-border-subtle)', overflow: 'hidden', marginBottom: '40px' }}>
                                        <div style={{ padding: '20px 24px', borderBottom: '1px solid var(--pos-border-subtle)', background: 'var(--pos-bg-main)' }}>
                                            <div style={{ fontSize: '14px', fontWeight: 900, color: 'var(--pos-text-primary)', textTransform: 'uppercase' }}>
                                                Ordered Items ({selectedOrder.items})
                                            </div>
                                        </div>
                                        <div style={{ padding: '8px 0' }}>
                                            {selectedOrder.itemsList.map((item, idx) => (
                                                <div key={idx} style={{
                                                    padding: '16px 24px',
                                                    display: 'flex',
                                                    justifyContent: 'space-between',
                                                    alignItems: 'center',
                                                    borderBottom: idx < selectedOrder.itemsList.length - 1 ? '1px solid var(--pos-border-subtle)' : 'none'
                                                }}>
                                                    <div style={{ fontSize: '16px', fontWeight: 700, color: 'var(--pos-text-primary)' }}>{item}</div>
                                                    <div style={{ width: '32px', height: '32px', background: 'var(--pos-bg-main)', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyItems: 'center', justifyContent: 'center', fontSize: '14px', fontWeight: 900 }}>1</div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>

                                    {/* Timeline & Summary */}
                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                                        <div style={{ background: 'white', padding: '24px', borderRadius: '20px', border: '1px solid var(--pos-border-subtle)' }}>
                                            <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 900, textTransform: 'uppercase', marginBottom: '16px' }}>Terminal Timeline</div>
                                            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span style={{ fontSize: '14px', color: 'var(--pos-text-secondary)', fontWeight: 600 }}>Thread Initiated</span>
                                                    <span style={{ fontSize: '14px', color: 'var(--pos-text-primary)', fontWeight: 700 }}>{selectedOrder.placedAt}</span>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span style={{ fontSize: '14px', color: 'var(--pos-text-secondary)', fontWeight: 600 }}>Est. Completion</span>
                                                    <span style={{ fontSize: '14px', color: 'var(--pos-text-primary)', fontWeight: 700 }}>{selectedOrder.estimatedReady}</span>
                                                </div>
                                                {selectedOrder.completedAt && (
                                                    <div style={{ display: 'flex', justifyContent: 'space-between', paddingTop: '8px', borderTop: '1px solid var(--pos-border-subtle)' }}>
                                                        <span style={{ fontSize: '14px', color: 'var(--pos-state-success)', fontWeight: 800 }}>FINALIZED</span>
                                                        <span style={{ fontSize: '14px', color: 'var(--pos-state-success)', fontWeight: 800 }}>{selectedOrder.completedAt}</span>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                        <div style={{ background: 'var(--pos-text-primary)', padding: '24px', borderRadius: '20px', color: 'white' }}>
                                            <div style={{ fontSize: '11px', color: 'rgba(255,255,255,0.4)', fontWeight: 900, textTransform: 'uppercase', marginBottom: '16px' }}>Financial Summary</div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                                                <span style={{ fontSize: '14px', opacity: 0.7 }}>Subtotal</span>
                                                <span style={{ fontSize: '14px', fontWeight: 700 }}>${(selectedOrder.total * 0.92).toFixed(2)}</span>
                                            </div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '24px' }}>
                                                <span style={{ fontSize: '14px', opacity: 0.7 }}>Tax (8%)</span>
                                                <span style={{ fontSize: '14px', fontWeight: 700 }}>${(selectedOrder.total * 0.08).toFixed(2)}</span>
                                            </div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', paddingTop: '16px', borderTop: '1px solid rgba(255,255,255,0.1)' }}>
                                                <span style={{ fontSize: '16px', fontWeight: 900 }}>TOTAL</span>
                                                <span style={{ fontSize: '40px', fontWeight: 900, lineHeight: 1, letterSpacing: '-0.02em' }}>${selectedOrder.total.toFixed(2)}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Actions Bar */}
                            <div style={{
                                padding: '24px 32px',
                                background: 'var(--pos-bg-surface)',
                                borderTop: '1px solid var(--pos-border-subtle)',
                                display: 'flex',
                                justifyContent: 'space-between',
                                gap: '16px'
                            }}>
                                <div style={{ display: 'flex', gap: '12px' }}>
                                    <button className="pos-btn pos-btn-secondary" style={{ width: '180px' }}>
                                        <Printer size={20} />
                                        PRINT KITCHEN
                                    </button>
                                    <button className="pos-btn pos-btn-secondary" style={{ width: '180px' }}>
                                        <Eye size={20} />
                                        AUDIT LOG
                                    </button>
                                </div>
                                <button className="pos-btn pos-btn-primary" style={{ width: '280px' }}>
                                    {selectedOrder.status === 'READY' ? 'COMPLETE ORDER' : 'MARK AS READY'}
                                </button>
                            </div>
                        </>
                    ) : (
                        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', opacity: 0.3 }}>
                            <Clock size={80} color="var(--pos-text-muted)" style={{ marginBottom: '24px' }} />
                            <div style={{ fontSize: '18px', fontWeight: 800, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.2em' }}>
                                MISSION SELECTION REQUIRED
                            </div>
                            <div style={{ fontSize: '14px', color: 'var(--pos-text-muted)', fontWeight: 600, marginTop: '8px' }}>
                                Select an active order thread to view operational telemetrics
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};
